command:
(async () => {
  const mode = args[0];
  console.log(`DAE mode=${mode}`, args);

  if (mode === "on") {
    const last = args.at(-1);
    if (!last?.effectUuid) return;

    const token = canvas.tokens.get(last.tokenId);
    const actor = token?.actor;
    if (!actor) return;

    let casterDoc = await fromUuid(last.origin);
    if (casterDoc?.documentName === "ActiveEffect") casterDoc = await fromUuid(casterDoc.origin);
    const caster = casterDoc?.actor || casterDoc;
    if (!caster) return;

    const saveDC = getProperty(caster, "system.attributes.spell.dc");
    if (!saveDC) return;

    const save = await actor.rollAbilitySave("str", { flavor: `Tentacles save vs DC ${saveDC}` });
    console.log("🎲 Save:", save.total, "vs", saveDC);

    if (save.total >= saveDC) {
      console.log("✅ Save succeeded — removing aura effect if present");
      // 使用 origin 删除 aura 效果
      const aura = actor.effects.find(e => e.origin === last.origin);
      if (aura) {
        await aura.delete();
        console.log("🧹 Removed aura effect by origin:", aura.origin);
      } else {
        console.log("⚠️ No aura effect matching origin:", last.origin);
      }
      return;
    }

    console.log("❌ Save failed — applying Tentacle B effect");
    const effectData = {
      label: "艾伐黑触手—束缚",
      icon: "modules/dnd5e_classpack/Nicons/spell_priest_voidtendrils.jpg",
      origin: last.origin,
      type: "base",
      system: {},
      changes: [{
        key: "flags.midi-qol.OverTime",
        mode: 0,
        value: "turn=start,allowIncapacitated=true,rollType=check,saveAbility=str,saveDC=@attributes.spell.dc,saveDamage=fulldamage,saveRemove=true,saveMagic=true,actionSave=dialog,damageBeforeSave=true,damageRoll=3d6,damageType=bludgeoning,rollMode=publicroll,",
        priority: 20
      },
        {
          "key": "macro.execute",
          "mode": 0,
          "value": "DeleteAuraEffect",
          "priority": 20
        }],
      duration: { rounds: 10 },
      statuses: ["restrained"],
      flags: { myTentacle: { origin: last.origin } }
    };
    await actor.createEmbeddedDocuments("ActiveEffect", [effectData]);
    console.log("✅ Tentacle B applied");
    return;
  }

  if (mode === "off") {
    console.log("🛠️ off mode — removal logic", args);
    const reply = args.at(-1) || {};
    const tokenId = args[1]?.tokenId || args[1]?.token?.id;
    const token = canvas.tokens.get(tokenId);
    const actor = token?.actor;
    if (!actor) return console.warn("No actor on removal");

    const originToDel = reply.origin || null;
    console.log("🔍 Looking for lingering effect with flag origin:", originToDel);

    const lingering = actor.effects.find(e => e.flags?.myTentacle?.origin === originToDel);
    if (lingering) {
      await lingering.delete();
      console.log("🧹 Removed lingering Tentacle B:", lingering.system.label);
    } else {
      console.log("✅ No lingering Tentacle B to remove");
    }
    ChatMessage.create({
      speaker: { token: token.id, actor: actor.id },
      content: `<p>“艾伐黑触手—束缚” 已被彻底移除。</p>`
    });
    return;
  }

  console.log("⚠️ Unknown mode:", mode);
})();
